struct Node {
    int key, val;
    Node *prev, *next;
    Node(int k = 0, int v = 0) : key(k), val(v), prev(nullptr), next(nullptr) {}
};
class LRUCache {
    int cap;
    unordered_map<int, Node*> mp;
    Node *head, *tail;
    void removeNode(Node* x) { x->prev->next = x->next; x->next->prev = x->prev; }
    void addFront(Node* x) { x->next = head->next; x->prev = head; head->next->prev = x; head->next = x; }
public:
    LRUCache(int capacity) : cap(capacity) {
        head = new Node(); tail = new Node();
        head->next = tail; tail->prev = head;
    }
    int get(int key) {
        auto it = mp.find(key);
        if (it == mp.end()) return -1;
        removeNode(it->second); addFront(it->second);
        return it->second->val;
    }
    void put(int key, int value) {
        auto it = mp.find(key);
        if (it != mp.end()) {
            it->second->val = value;
            removeNode(it->second); addFront(it->second);
            return;
        }
        if ((int)mp.size() == cap) {
            Node* last = tail->prev;
            removeNode(last); mp.erase(last->key); delete last;
        }
        Node* x = new Node(key, value);
        mp[key] = x; addFront(x);
    }
};
